class Solution {
public:
    long long minimumMoney(std::vector<std::vector<int>>& transactions) {
        long long total_loss = 0;
        long long max_extra = 0;
        for (const auto& t : transactions) {
            long long cost = t[0], cashback = t[1];
            if (cost > cashback) {
                total_loss += cost - cashback;
                max_extra = std::max(max_extra, cashback);
            } else {
                max_extra = std::max(max_extra, cost);
            }
        }
        return total_loss + max_extra;
    }
};

class Solution {
    public long minimumMoney(int[][] transactions) {
        long totalLoss = 0;
        long maxExtra = 0;
        for (int[] t : transactions) {
            long cost = t[0], cashback = t[1];
            if (cost > cashback) {
                totalLoss += cost - cashback;
                maxExtra = Math.max(maxExtra, cashback);
            } else {
                maxExtra = Math.max(maxExtra, cost);
            }
        }
        return totalLoss + maxExtra;
    }
}

var minimumMoney = function(transactions) {
    let totalLoss = 0n;
    let maxExtra = 0n;
    for (const [cost, cashback] of transactions) {
        const c = BigInt(cost), cb = BigInt(cashback);
        if (c > cb) {
            totalLoss += c - cb;
            if (cb > maxExtra) maxExtra = cb;
        } else {
            if (c > maxExtra) maxExtra = c;
        }
    }
    return Number(totalLoss + maxExtra);
};
